        { float t = D_002DDED0.time; behavior->wakeTime = t + RandomFloatInRange__Fff(((STEPGUARD *)behavior->owner)->sleepTimeMin, ((STEPGUARD *)behavior->owner)->sleepTimeMax); }
        break;
