    do {
        s = behavior->sleepState;
        if (s == 0 && D_002DDED0.time > behavior->wakeTime) SetBhvSleepState(behavior, 1);
    } while (behavior->sleepState != s);
    {
        STEPGUARD *t = (STEPGUARD *)behavior->owner;
        CID147 *v = t->heldNoise;
        v->position = GetLoWorldPos(t);
    }
